import ctypes
import errno
import os
import random
import re
import shutil
import signal
import string
import subprocess
import sys
import termios
import time
import unicodedata
from datetime import datetime

# ---------------------------------------------------------------------------
# small helpers

def io_error_str(e):
    """Format an OSError the way Rust's std::io::Error Display does."""
    if isinstance(e, OSError) and e.errno is not None:
        return f"{os.strerror(e.errno)} (os error {e.errno})"
    return str(e)


def rust_debug_str(s):
    out = s.replace("\\", "\\\\").replace('"', '\\"')
    out = out.replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
    return '"' + out + '"'


def rust_debug_list(items):
    return "[" + ", ".join(rust_debug_str(str(x)) for x in items) + "]"


def char_width(ch):
    if ch == "\t":
        return 8
    o = ord(ch)
    if o == 0:
        return 0
    if o < 32 or (0x7F <= o < 0xA0):
        return 0
    if unicodedata.combining(ch):
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    return 1


def text_width(s):
    w = 0
    for ch in s:
        if ch == "\t":
            w += 8 - (w % 8)
        else:
            w += char_width(ch)
    return w


def truncate_width(s, width):
    """Truncate to display width, adding '..' if truncated (felix style)."""
    if width <= 0:
        return ""
    if text_width(s) <= width:
        return s
    if width <= 2:
        # at tiny widths the original shows '..' style clipping
        return "." * width
    limit = width - 2
    out = []
    w = 0
    for ch in s:
        cw = char_width(ch)
        if cw == 0:
            continue
        if w + cw > limit:
            break
        out.append(ch)
        w += cw
    return "".join(out) + ".."


def clip_width(s, width):
    """Clip to display width without ellipsis."""
    if width <= 0:
        return ""
    out = []
    w = 0
    for ch in s:
        cw = char_width(ch)
        if cw == 0 and ch != "\t":
            continue
        if ch == "\t":
            step = 8 - (w % 8)
            if w + step > width:
                break
            out.append(ch)
            w += step
            continue
        if w + cw > width:
            break
        out.append(ch)
        w += cw
    return "".join(out)


def split_width(s, width):
    """Split a string into chunks of at most `width` display columns."""
    if width <= 0:
        return [""]
    chunks = []
    cur = []
    w = 0
    for ch in s:
        if ch == "\t":
            step = 8 - (w % 8)
            if w + step > width and cur:
                chunks.append("".join(cur))
                cur = []
                w = 0
                step = 8
            cur.append(ch)
            w += step
            continue
        cw = char_width(ch)
        if cw == 0:
            continue
        if w + cw > width and cur:
            chunks.append("".join(cur))
            cur = []
            w = 0
        cur.append(ch)
        w += cw
    chunks.append("".join(cur))
    return chunks


def _is_digit(ch):
    return "0" <= ch <= "9"


def _digit_run_cmp(a, b):
    """Compare two digit runs (version-sort like behaviour)."""
    a_zero = a.startswith("0")
    b_zero = b.startswith("0")
    if a_zero and not b_zero:
        return -1
    if b_zero and not a_zero:
        return 1
    if a_zero and b_zero:
        if a == b:
            return 0
        return -1 if a < b else 1
    an = a.lstrip("0") or "0"
    bn = b.lstrip("0") or "0"
    if len(an) != len(bn):
        return -1 if len(an) < len(bn) else 1
    if an == bn:
        return 0
    return -1 if an < bn else 1


def natural_cmp(a, b, case_insensitive=True):
    ia = ib = 0
    la, lb = len(a), len(b)
    while ia < la and ib < lb:
        ca, cb = a[ia], b[ib]
        if _is_digit(ca) and _is_digit(cb):
            ja = ia
            while ja < la and _is_digit(a[ja]):
                ja += 1
            jb = ib
            while jb < lb and _is_digit(b[jb]):
                jb += 1
            c = _digit_run_cmp(a[ia:ja], b[ib:jb])
            if c:
                return c
            ia, ib = ja, jb
            continue
        ka = ca.lower() if case_insensitive else ca
        kb = cb.lower() if case_insensitive else cb
        if ka != kb:
            return -1 if ka < kb else 1
        ia += 1
        ib += 1
    if ia < la:
        return 1
    if ib < lb:
        return -1
    return 0


def stem_ext(name):
    """Rust Path::file_stem / extension semantics. Returns (stem, ext|None)."""
    if name in (".", ".."):
        return name, None
    idx = name.rfind(".")
    if idx <= 0:
        return name, None
    return name[:idx], name[idx + 1:]


def unique_append_version(path, is_dir):
    """path -> path_1, path_2 ... (put style, stem based for files)."""
    if not os.path.lexists(path):
        return path
    dirname = os.path.dirname(path)
    name = os.path.basename(path)
    i = 1
    while True:
        if is_dir:
            cand_name = f"{name}_{i}"
        else:
            stem, ext = stem_ext(name)
            cand_name = f"{stem}_{i}" if ext is None else f"{stem}_{i}.{ext}"
        cand = os.path.join(dirname, cand_name)
        if not os.path.lexists(cand):
            return cand
        i += 1


def unique_full_suffix(path):
    """path -> path_1 ... (unpack style, full name suffix)."""
    if not os.path.lexists(path):
        return path
    i = 1
    while True:
        cand = f"{path}_{i}"
        if not os.path.lexists(cand):
            return cand
        i += 1


def format_size(size):
    if size < 1000:
        return f"{size}B"
    if size < 1000 * 1000:
        return f"{size // 1000}KB"
    if size < 1000 * 1000 * 1000:
        return f"{size // (1000 * 1000)}MB"
    return f"{size // (1000 * 1000 * 1000)}GB"

