def _yaml_scalar(tok):
    tok = tok.strip()
    if tok == "" or tok in ("~", "null", "Null", "NULL"):
        return None
    if tok.startswith("!"):
        # tagged value, e.g. !AnsiValue 14 or !Rgb [1, 2, 3]
        parts = tok.split(None, 1)
        tag = parts[0][1:]
        rest = parts[1] if len(parts) > 1 else ""
        return ("__tag__", tag, _yaml_scalar(rest) if not rest.startswith("[") else _yaml_flow(rest))
    if tok.startswith("["):
        return _yaml_flow(tok)
    if tok.startswith("{"):
        return _yaml_flow(tok)
    if len(tok) >= 2 and tok[0] == "'" and tok[-1] == "'":
        return tok[1:-1].replace("''", "'")
    if len(tok) >= 2 and tok[0] == '"' and tok[-1] == '"':
        try:
            import codecs
            return codecs.decode(tok[1:-1], "unicode_escape")
        except Exception:
            return tok[1:-1]
    # strip trailing comment on plain scalars
    if " #" in tok:
        tok = tok.split(" #", 1)[0].rstrip()
    low = tok.lower()
    if low in ("true", "yes", "on"):
        return True
    if low in ("false", "no", "off"):
        return False
    try:
        return int(tok)
    except ValueError:
        pass
    try:
        return float(tok)
    except ValueError:
        pass
    return tok


def _yaml_flow(tok):
    tok = tok.strip()
    if tok.startswith("["):
        if not tok.endswith("]"):
            raise ConfigError("did not find expected ',' or ']'")
        inner = tok[1:-1].strip()
        if not inner:
            return []
        parts = []
        depth = 0
        cur = ""
        for ch in inner:
            if ch in "[{":
                depth += 1
            elif ch in "]}":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        if cur.strip():
            parts.append(cur)
        return [_yaml_scalar(p) for p in parts]
    if tok.startswith("{"):
        if not tok.endswith("}"):
            raise ConfigError("did not find expected ',' or '}'")
        inner = tok[1:-1].strip()
        out = {}
        if not inner:
            return out
        parts = []
        depth = 0
        cur = ""
        for ch in inner:
            if ch in "[{":
                depth += 1
            elif ch in "]}":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        if cur.strip():
            parts.append(cur)
        for p in parts:
