    if vals.get("sort_by") not in ("Name", "Time"):
        return dict(defaults)
    if vals.get("show_hidden") not in ("true", "false"):
        return dict(defaults)
    if vals.get("preview") not in ("true", "false"):
        return dict(defaults)
    if vals.get("split") not in ("Vertical", "Horizontal"):
        return dict(defaults)
    return {
        "sort_by": vals["sort_by"],
        "show_hidden": vals["show_hidden"] == "true",
        "preview": vals["preview"] == "true",
        "split": vals["split"],
    }


