# terminal handling

def fg_code(color):
    if color is None:
        return None
    kind, val = color
    if kind == "pal":
        if val < 8:
            return str(30 + val)
        return str(90 + (val - 8))
    if kind == "ansi":
        return f"38;5;{val}"
    if kind == "rgb":
        return f"38;2;{val[0]};{val[1]};{val[2]}"
    return None


def bg_code(color):
    if color is None:
        return None
    kind, val = color
    if kind == "pal":
        if val < 8:
            return str(40 + val)
        return str(100 + (val - 8))
    if kind == "ansi":
        return f"48;5;{val}"
    if kind == "rgb":
        return f"48;2;{val[0]};{val[1]};{val[2]}"
    return None


# styles are tuples (fg, bg, bold, reverse)
STYLE_DEFAULT = (None, None, False, False)


class Screen:
    def __init__(self, w, h):
        self.w = w
        self.h = h
        self.cells = [[[" ", None, None, False, False] for _ in range(w)] for _ in range(h)]

    def clear(self):
        for y in range(self.h):
            for x in range(self.w):
                self.cells[y][x] = [" ", None, None, False, False]

    def put(self, x, y, ch, style=STYLE_DEFAULT):
        if 0 <= x < self.w and 0 <= y < self.h:
            self.cells[y][x] = [ch, style[0], style[1], style[2], style[3]]

    def text(self, x, y, s, style=STYLE_DEFAULT):
        cx = x
        for ch in s:
            if ch == "\t":
                step = 8 - (cx % 8)
                cx += step
                continue
