    parts.append("\x1b[0m")
    return "".join(parts)


class Event:
    def __init__(self, kind, value=None, mods=()):
        self.kind = kind      # 'char' | 'key' | 'resize'
        self.value = value    # char or key name
        self.mods = frozenset(mods)

    def __repr__(self):
        return f"Event({self.kind},{self.value!r},{sorted(self.mods)})"


class Terminal:
    def __init__(self):
        self.fd_in = 0
        self.fd_out = 1
        self.saved = None
        self.raw = False
        self.buffer = bytearray()
        self.resize_pending = False

    def size(self):
        sz = os.get_terminal_size(self.fd_out)
        return sz.columns, sz.lines

    def set_raw(self):
        if self.saved is None:
            self.saved = termios.tcgetattr(self.fd_in)
        attrs = termios.tcgetattr(self.fd_in)
        # like crossterm raw mode
        attrs[0] &= ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
        attrs[1] &= ~termios.OPOST
        attrs[2] |= termios.CS8
        attrs[3] &= ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
        attrs[6][termios.VMIN] = 1
        attrs[6][termios.VTIME] = 0
        termios.tcsetattr(self.fd_in, termios.TCSANOW, attrs)
        self.raw = True

    def restore_mode(self):
        if self.saved is not None:
            try:
                termios.tcsetattr(self.fd_in, termios.TCSANOW, self.saved)
            except Exception:
                pass
        self.raw = False

    def enter(self):
        self.set_raw()
        os.write(self.fd_out, b"\x1b[?1049h\x1b[?25l\x1b[2J\x1b[H")

    def leave(self):
        try:
            os.write(self.fd_out, b"\x1b[0m\x1b[?25h\x1b[?1049l")
        except Exception:
            pass
        self.restore_mode()

    def suspend(self):
        # for external programs: cooked mode, stay in alternate screen
        try:
            os.write(self.fd_out, b"\x1b[?25h")
        except Exception:
            pass
        self.restore_mode()

    def resume(self):
        self.set_raw()
        try:
            os.write(self.fd_out, b"\x1b[?25l\x1b[2J\x1b[H")
        except Exception:
            pass

    # ---------------- input ----------------
    def poll_event(self, timeout=0.05):
        import select
        if self.resize_pending:
            self.resize_pending = False
            return Event("resize")
        # try parse from buffer first
        ev = self._try_parse()
        if ev is not None:
            return ev
        r, _, _ = select.select([self.fd_in], [], [], timeout)
        if not r:
            # if buffer holds a lone ESC, emit it
            if self.buffer:
                ev = self._try_parse(final=True)
                if ev is not None:
                    return ev
            return None
        try:
            data = os.read(self.fd_in, 65536)
        except OSError:
            return Event("eof")
        if not data:
            return Event("eof")
        self.buffer.extend(data)
        ev = self._try_parse()
        return ev

    def _decode_char(self, data, pos):
        # decode one utf-8 char starting at pos; return (char, nextpos) or (None,pos)
        b = data[pos]
        if b < 0x80:
            return chr(b), pos + 1
        for ln in (2, 3, 4):
            if pos + ln <= len(data):
                try:
                    return bytes(data[pos:pos + ln]).decode("utf-8"), pos + ln
                except Exception:
                    continue
        return None, pos

    def _try_parse(self, final=False):
        buf = self.buffer
        if not buf:
            return None
        b = buf[0]
        if b == 0x1B:
            if len(buf) == 1:
                if final:
                    del buf[0]
                    return Event("key", "Esc")
                return None
            nxt = buf[1]
            if nxt == 0x5B:  # CSI
                # find final byte
                i = 2
                while i < len(buf) and not (0x40 <= buf[i] <= 0x7E):
                    i += 1
                if i >= len(buf):
                    if final:
                        del buf[:]
                    return None
                params = bytes(buf[2:i]).decode("ascii", "ignore")
                finalb = chr(buf[i])
                raw = bytes(buf[:i + 1])
                del buf[:i + 1]
                return self._csi_event(params, finalb, raw)
            if nxt == 0x4F:  # SS3
                if len(buf) < 3:
                    return None
                code = chr(buf[2])
                del buf[:3]
                names = {"A": "Up", "B": "Down", "C": "Right", "D": "Left", "H": "Home", "F": "End", "P": "F1", "Q": "F2", "R": "F3", "S": "F4"}
                return Event("key", names.get(code, code))
            # Alt + char
            ch, np = self._decode_char(buf, 1)
            if ch is None:
                return None
            del buf[:np]
            return self._char_event(ch, alt=True)
        if b in (0x0D,):
            del buf[0]
            return Event("key", "Enter")
        if b == 0x0A:
            del buf[0]
            return Event("char", "j", ("ctrl",))
        if b == 0x09:
            del buf[0]
            return Event("key", "Tab")
        if b == 0x7F:
            del buf[0]
            return Event("key", "Backspace")
        if b == 0x08:
            del buf[0]
            return Event("char", "h", ("ctrl",))
        if 0x01 <= b <= 0x1A:
            del buf[0]
            return Event("char", chr(0x60 + b), ("ctrl",))
        if b == 0x00:
            del buf[0]
            return Event("char", " ", ("ctrl",))
        if b == 0x1F:
            del buf[0]
            return Event("char", "/", ("ctrl",))
        ch, np = self._decode_char(buf, 0)
        if ch is None:
            if final:
                del buf[0]
            return None
        del buf[:np]
        return self._char_event(ch)

    def _char_event(self, ch, alt=False, ctrl=False):
        mods = []
        if alt:
            mods.append("alt")
        if ctrl:
            mods.append("ctrl")
        return Event("char", ch, mods)

    def _csi_event(self, params, finalb, raw):
        # mouse: ignore
        if params.startswith("<"):
            return Event("mouse")
        if finalb == "Z":
            return Event("key", "BackTab")
        # modifiers
        mods = []
        modnum = 1
        base = params
        if ";" in params:
            parts = params.split(";")
            base = parts[0]
            try:
                modnum = int(parts[1]) if parts[1] else 1
            except Exception:
                modnum = 1
        mm = modnum - 1
        if mm & 1:
            mods.append("alt")
        if mm & 2:
            mods.append("shift")
        if mm & 4:
            mods.append("ctrl")
        arrows = {"A": "Up", "B": "Down", "C": "Right", "D": "Left", "H": "Home", "F": "End"}
        if finalb in arrows:
            return Event("key", arrows[finalb], mods)
        if finalb == "~":
            try:
                code = int(base) if base else 1
            except Exception:
                code = 1
            names = {1: "Home", 2: "Insert", 3: "Delete", 4: "End", 5: "PageUp", 6: "PageDown", 7: "Home", 8: "End",
                     11: "F1", 12: "F2", 13: "F3", 14: "F4", 15: "F5", 17: "F6", 18: "F7", 19: "F8", 20: "F9", 21: "F10", 23: "F11", 24: "F12"}
            return Event("key", names.get(code, "Unknown"), mods)
        return Event("key", "Unknown", mods)

