# ---------------------------------------------------------------------------
# archive handling

def zstd_decompress(data):
    lib = ctypes.CDLL("libzstd.so.1")
    lib.ZSTD_createDCtx.restype = ctypes.c_void_p
    lib.ZSTD_freeDCtx.argtypes = [ctypes.c_void_p]
    lib.ZSTD_decompressStream_simpleArgs = None
    # Use the streaming API via ZSTD_decompressStream
    class InBuf(ctypes.Structure):
        _fields_ = [("src", ctypes.c_void_p), ("size", ctypes.c_size_t), ("pos", ctypes.c_size_t)]

    class OutBuf(ctypes.Structure):
        _fields_ = [("dst", ctypes.c_void_p), ("size", ctypes.c_size_t), ("pos", ctypes.c_size_t)]

    lib.ZSTD_decompressStream.argtypes = [ctypes.c_void_p, ctypes.POINTER(OutBuf), ctypes.POINTER(InBuf)]
    lib.ZSTD_decompressStream.restype = ctypes.c_size_t
    lib.ZSTD_isError.argtypes = [ctypes.c_size_t]
    lib.ZSTD_isError.restype = ctypes.c_uint
    lib.ZSTD_getErrorName.argtypes = [ctypes.c_size_t]
    lib.ZSTD_getErrorName.restype = ctypes.c_char_p
    ctx = lib.ZSTD_createDCtx()
    if not ctx:
        raise Exception("zstd: no context")
    src = ctypes.create_string_buffer(data, len(data))
    out_chunks = []
    inb = InBuf(ctypes.cast(src, ctypes.c_void_p), len(data), 0)
    try:
        while inb.pos < inb.size:
            chunk = ctypes.create_string_buffer(131072)
            outb = OutBuf(ctypes.cast(chunk, ctypes.c_void_p), 131072, 0)
            ret = lib.ZSTD_decompressStream(ctx, ctypes.byref(outb), ctypes.byref(inb))
            if lib.ZSTD_isError(ret):
                msg = lib.ZSTD_getErrorName(ret)
                raise Exception(msg.decode() if msg else "zstd error")
            if outb.pos:
                out_chunks.append(chunk.raw[:outb.pos])
            if ret == 0:
                break
    finally:
        lib.ZSTD_freeDCtx(ctx)
    return b"".join(out_chunks)


def detect_magic(data):
    """Return a kind string describing the file type, or None."""
    if len(data) >= 4 and data[:4] == b"PK\x03\x04":
        return "zip"
    if len(data) >= 2 and data[:2] == b"\x1f\x8b":
        return "gzip"
    if len(data) >= 6 and data[:6] == bytes([0xFD, 0x37, 0x7A, 0x58, 0x5A, 0x00]):
        return "xz"
    if len(data) >= 4 and data[:4] == bytes([0x28, 0xB5, 0x2F, 0xFD]):
        return "zstd"
    if len(data) >= 4 and data[:3] == b"BZh" and chr(data[3]) in "123456789":
        return "Bzip2"
    if len(data) >= 6 and data[:6] == bytes([0x37, 0x7A, 0xBC, 0xAF, 0x27, 0x1C]):
        return "7z"
    if len(data) >= 7 and data[:7] == b"Rar!\x1a\x07\x00":
        return "rar v1.50"
    if len(data) >= 8 and data[:8] == b"Rar!\x1a\x07\x01\x00":
        return "rar v5"
    if is_tar_data(data):
        return "tar"
    return None


def is_tar_data(data):
    if len(data) < 512:
        return False
    block = data[:512]
    if not block[:100].split(b"\x00")[0]:
        return False
    if block[257:262] != b"ustar":
        return False
    # verify checksum
    try:
        stored = block[148:156].split(b"\x00")[0].strip()
        chksum = int(stored, 8) if stored else 0
    except Exception:
        return False
    calc = sum(block[:148]) + 8 * 32 + sum(block[156:512])
    return calc == chksum

