# ---------------------------------------------------------------------------
# the application

class PanicError(Exception):
    pass


class Item:
    __slots__ = ("path", "name", "is_dir", "is_symlink", "size", "perm", "mtime", "ext", "dirty")

    def __init__(self, path, name, is_dir, is_symlink, size, perm, mtime, ext, dirty=False):
        self.path = path
        self.name = name
        self.is_dir = is_dir
        self.is_symlink = is_symlink
        self.size = size
        self.perm = perm
        self.mtime = mtime
        self.ext = ext
        self.dirty = dirty


class App:
    def __init__(self, start_dir, config, logger, data_dir, cfg_file_exists_dir=None):
        self.cwd = start_dir
        self.config = config
        self.logger = logger
        self.data_dir = data_dir
        self.trash_dir = trash_dir_path()
        self.config_dir = config_dir_path()
        sess = read_session(data_dir)
        self.sort_by = sess["sort_by"]
        self.show_hidden = sess["show_hidden"]
        self.preview = sess["preview"]
        self.split = sess["split"]
        self.items = []
        self.cursor = 0
        self.offset = 0
        self.message = None          # (text, is_warn)
        self.pending = ""
        self.pending_weird_digit = False
        self.mode = "normal"          # normal | visual
        self.visual_anchor = 0
        self.prompt = None            # dict kind, buf, cur, awaiting
        self.help_mode = False
        self.help_scroll = 0
        self.confirm_empty = False
        self.show_registers = False
        self.search_keyword = None
        self.preview_scroll = 0
        self.registers = {}           # char -> list of (src_path, display_name)
        self.undo_stack = []
        self.redo_stack = []
        self.history = [start_dir]
        self.history_index = 0
        self.git_branch = None
        self.git_dirty = set()
        self.zoxide_available = False
        self.chafa_available = False
        self.term = None
        self.exited = False
        self.exit_code = 0
        self._preview_cache = {}
        self._frame_cursor = (0, 2, False)
        self.help_lines = HELP_TEXT.split("\n")
        # HELP_TEXT ends with a newline; drop the final empty piece and
        # append the extra lines shown in the help screen
        if self.help_lines and self.help_lines[-1] == "":
            self.help_lines = self.help_lines[:-1]
        self.help_lines = self.help_lines + ["", "Press <CR> to go back."]

    # ------------------------------------------------------------------
    # logging/message helpers
    def set_message(self, text, warn=False, log=True):
        self.message = (text, warn)
        if log:
            if warn:
                self.logger.warn(text)
            else:
                self.logger.info(text)

    def clear_message(self):
        self.message = None

    def io_warn(self, e):
        msg = io_error_str(e) if isinstance(e, BaseException) else str(e)
        self.set_message(msg, warn=True)

    # ------------------------------------------------------------------
    # directory loading
    def git_info(self, path):
        branch = None
        dirty = set()
        dotgit = os.path.join(path, ".git")
        gitdir = None
        if os.path.isdir(dotgit):
            gitdir = dotgit
        elif os.path.isfile(dotgit):
            try:
                for line in open(dotgit):
                    if line.startswith("gitdir:"):
                        gd = line.split(":", 1)[1].strip()
                        gitdir = gd if os.path.isabs(gd) else os.path.join(path, gd)
                        break
            except Exception:
                gitdir = None
        if gitdir is None:
            return None, dirty
        # branch
        try:
            head = open(os.path.join(gitdir, "HEAD")).read().strip()
            if head.startswith("ref:"):
                ref = head[4:].strip()
                name = ref
                if ref.startswith("refs/heads/"):
                    name = ref[len("refs/heads/"):]
                # ref must resolve (born branch)
                refpath = os.path.join(gitdir, ref)
                born = os.path.exists(refpath)
                if not born:
                    packed = os.path.join(gitdir, "packed-refs")
                    if os.path.exists(packed):
                        for line in open(packed):
                            if line.strip().endswith(ref):
                                born = True
                                break
                if born:
                    branch = name
            elif head:
                branch = "HEAD"
        except Exception:
            pass
        # dirty (work-tree) statuses
        try:
            out = subprocess.run(
                ["git", "-C", path, "status", "--porcelain=v1", "-z",
                 "--untracked-files=normal"],
                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=5)
            if out.returncode == 0:
                parts = out.stdout.split(b"\x00")
                i = 0
                while i < len(parts):
                    rec = parts[i]
                    i += 1
