    # ------------------------------------------------------------------
    # navigation
    def change_dir(self, target, select_child=None, from_history=False):
        try:
            items, branch, dirty = self.load_items(target)
        except Exception as e:
            self.io_warn(e)
            return False
        canonical = os.path.realpath(target)
        self.cwd = canonical
        # reload items for the canonical path if it differs
        if canonical != target:
            try:
                items, branch, dirty = self.load_items(canonical)
            except Exception:
                pass
        self.items = items
        self.git_branch = branch
        self.git_dirty = dirty
        self.search_keyword = None
        self.preview_scroll = 0
        if select_child is not None:
            self.cursor = 0
            for i, it in enumerate(items):
                if it.name == select_child:
                    self.cursor = i
                    break
            self.offset = 0
            self.ensure_visible()
        else:
            self.cursor = 0
            self.offset = 0
        if not from_history:
            del self.history[self.history_index + 1:]
            self.history.append(self.cwd)
            self.history_index = len(self.history) - 1
        if self.zoxide_available:
            try:
                subprocess.run(["zoxide", "add", self.cwd],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                               timeout=5)
            except Exception:
                pass
        self.clear_message()
        return True

    def go_parent(self):
        parent = os.path.dirname(self.cwd)
        if parent == self.cwd or not parent:
            return
        child = os.path.basename(self.cwd)
        self.change_dir(parent, select_child=child)

    def go_child_or_open(self):
        item = self.selected()
        if item is None:
            return
        if item.is_dir:
            self.change_dir(item.path)
        else:
            self.open_in_editor(item.path)

    def jump_history(self, delta):
        idx = self.history_index + delta
        if idx < 0 or idx >= len(self.history):
            return
        target = self.history[idx]
        try:
            items, branch, dirty = self.load_items(target)
        except Exception as e:
            self.io_warn(e)
            return
        self.history_index = idx
        self.cwd = target
        self.items = items
        self.git_branch = branch
        self.git_dirty = dirty
        self.search_keyword = None
        self.preview_scroll = 0
        self.cursor = 0
        self.offset = 0
        if self.zoxide_available:
            try:
                subprocess.run(["zoxide", "add", self.cwd],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=5)
            except Exception:
                pass
        self.clear_message()

    def home_dir(self):
        return os.path.expanduser("~")

    # ------------------------------------------------------------------
    # movement
    def move_by(self, n):
        if not self.items:
            return
        self.cursor = max(0, min(len(self.items) - 1, self.cursor + n))
        self.preview_scroll = 0
        self.ensure_visible()

    def move_half(self, direction):
        self.clear_message()
        if not self.items:
            return
        _, h = self.term_size()
        step = h // 2
        self.cursor = max(0, min(len(self.items) - 1, self.cursor + direction * step))
        self.preview_scroll = 0
        self.ensure_visible()

    def go_top(self):
        self.clear_message()
        self.cursor = 0
        self.offset = 0
        self.preview_scroll = 0

    def go_bottom(self):
        if not self.items:
            return
        self.cursor = len(self.items) - 1
        self.offset = max(0, len(self.items) - self.list_height())
        self.preview_scroll = 0

    # ------------------------------------------------------------------
    # registers
    def make_entries(self, items):
