            self.set_message("No item renamed.")
        else:
            for (old, new) in pairs:
                try:
                    os.rename(old, new)
                except OSError as e:
                    self.io_warn(e)
                    self.mode = "normal"
                    self.reload()
                    return
            self.logger.info("RENAME: " + rust_debug_list([f'"{o}" -> "{n}"' for (o, n) in pairs]))
            if len(pairs) == 1:
                self.set_message("1 item renamed.")
            else:
                self.set_message(f"{len(pairs)} items renamed.")
        self.mode = "normal"
        self.reload()

    # ------------------------------------------------------------------
    # editor / exec / shell
    def resolve_editor(self):
        if self.config.default_editor:
            return self.config.default_editor
        ed = os.environ.get("EDITOR")
        if ed:
            return ed
        return None

    def run_external(self, argv):
        """Run a blocking external program (editor/shell). Returns spawn ok."""
        if self.term is not None:
            self.term.suspend()
        try:
            proc = subprocess.run(argv)
            _ = proc
            return True
        except Exception:
            return False
        finally:
            if self.term is not None:
                self.term.resume()

    def open_in_editor(self, path):
        self.logger.info("OPEN: " + rust_debug_str(path))
        editor = self.resolve_editor()
        if editor is None:
            self.set_message("$EDITOR may not be set, or config file may be invalid.", warn=True)
            return
        ok = self.run_external([editor, path])
        if not ok:
            self.set_message("$EDITOR may not be set, or config file may be invalid.", warn=True)
            return
        self.clear_message()
        self.reload()

    def open_new_window(self):
        item = self.selected()
        if item is None:
            return
        if item.is_dir:
            return
        self.logger.info("OPEN(new window): " + rust_debug_str(item.path))
        if not self.config.exec_map:
            self.set_message("No exec configuration", warn=True)
            return
        ext = item.ext if item.ext is not None else ""
        program = None
        for prog, exts in self.config.exec_map.items():
            if ext in exts:
                program = prog
                break
        if program is None:
            self.set_message("Cannot open this type of item in new window", warn=True)
            return
        try:
            subprocess.Popen([program, item.path],
                             stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL)
        except Exception:
            pass
        self.clear_message()

    def exec_shell_command(self, cmdline):
        tokens = cmdline.split()
        self.logger.info("SHELL: " + rust_debug_list(tokens))
        shell = os.environ.get("SHELL")
        if shell is None:
            return
        if self.term is not None:
            self.term.suspend()
        try:
            subprocess.run([shell, "-c", cmdline], cwd=self.cwd)
            ok = True
        except Exception:
            ok = False
        finally:
            if self.term is not None:
                self.term.resume()
        if not ok:
            self.set_message("Command execution failed.", warn=True)
            return
        self.clear_message()
        self.reload()

