    # ------------------------------------------------------------------
    # prompts
    def start_prompt(self, kind):
        if kind == "jump_z" and not self.zoxide_available:
            self.set_message("zoxide not found.", warn=True)
            return
        if kind == "rename" and self.selected() is None:
            return
        self.clear_message()
        self.pending = ""
        buf = ""
        if kind == "command":
            buf = ":"
        elif kind == "search":
            buf = "/"
        elif kind == "jump_z":
            buf = "z"
        elif kind == "rename":
            buf = self.selected().name
        self.prompt = {"kind": kind, "buf": buf, "cur": len(buf), "awaiting": False}

    def prompt_insert(self, text):
        buf = self.prompt["buf"]
        cur = self.prompt["cur"]
        self.prompt["buf"] = buf[:cur] + text + buf[cur:]
        self.prompt["cur"] = cur + len(text)
        if self.prompt["kind"] == "search":
            self.incremental_search()

    def prompt_backspace(self):
        cur = self.prompt["cur"]
        if cur <= 0:
            return
        buf = self.prompt["buf"]
        self.prompt["buf"] = buf[:cur - 1] + buf[cur:]
        self.prompt["cur"] = cur - 1
        if self.prompt["kind"] == "search":
            self.incremental_search()

    def handle_prompt_event(self, ev):
        kind = self.prompt["kind"]
        if self.prompt["awaiting"]:
            if ev.kind == "key" and ev.value == "Esc":
                self.prompt["awaiting"] = False
                return
            if ev.kind == "char":
                ch = ev.value
                self.prompt["awaiting"] = False
                entries = self.registers.get(ch)
                if entries:
                    text = " ".join(disp for (_s, disp) in entries)
                    self.prompt_insert(text)
                return
            self.prompt["awaiting"] = False
            return
        if ev.kind == "key" and ev.value == "Esc":
            self.prompt = None
            self.clear_message()
            return
        if ev.kind == "key" and ev.value == "Enter":
            if kind == "command":
                self.execute_command_line()
            elif kind == "search":
                self.confirm_search()
                self.clear_message()
            elif kind == "create_file":
                name = self.prompt["buf"]
                self.prompt = None
                self.create_item(name, False)
            elif kind == "create_dir":
                name = self.prompt["buf"]
                self.prompt = None
                self.create_item(name, True)
            elif kind == "rename":
                name = self.prompt["buf"]
                self.prompt = None
                self.rename_single(name)
            elif kind == "jump_z":
                self.execute_z()
            return
        if ev.kind == "key" and ev.value == "Backspace":
            self.prompt_backspace()
            return
        if ev.kind == "key" and ev.value == "Left":
            self.prompt["cur"] = max(0, self.prompt["cur"] - 1)
            return
        if ev.kind == "key" and ev.value == "Right":
            self.prompt["cur"] = min(len(self.prompt["buf"]), self.prompt["cur"] + 1)
            return
        if ev.kind == "char":
            ch = ev.value
            if "ctrl" in ev.mods:
                if ch == "h":
                    self.prompt_backspace()
                    return
                if ch == "r" and kind in ("command", "create_file", "create_dir", "rename"):
                    self.prompt["awaiting"] = True
                    return
                # other ctrl+letters insert the letter itself
                self.prompt_insert(ch)
                return
            if "alt" in ev.mods:
                return
            self.prompt_insert(ch)
            return

    # ------------------------------------------------------------------
    # normal / visual key handling
    def handle_help_event(self, ev):
        if (ev.kind == "char" and ev.value == "j" and not ev.mods) or (ev.kind == "key" and ev.value == "Down"):
            self.help_scroll += 1
        elif (ev.kind == "char" and ev.value == "k" and not ev.mods) or (ev.kind == "key" and ev.value == "Up"):
            self.help_scroll = max(0, self.help_scroll - 1)
        else:
            self.help_mode = False

    def dispatch_open(self):
        self.go_child_or_open()

    def toggle_hidden(self):
        self.clear_message()
        self.show_hidden = not self.show_hidden
        self.cursor = 0
        self.offset = 0
        self.reload(keep_cursor=False)

    def toggle_sort(self):
        self.clear_message()
        self.sort_by = "Time" if self.sort_by == "Name" else "Name"
        self.cursor = 0
        self.offset = 0
        self.reload(keep_cursor=False)

    def toggle_preview_key(self):
        self.clear_message()
        if self.show_registers:
            self.show_registers = False
            self.preview = False
        else:
            self.preview = not self.preview

    def handle_pending(self, ch):
        cand = self.pending + ch
        if self.pending_weird_digit:
            self.pending = ""
            self.pending_weird_digit = False
            self.clear_message()
            self.handle_normal_char(ch)
            return
        # complete simple sequences
        if cand == "gg":
            self.pending = ""
            self.go_top()
            return
        if cand in ("ZZ", "ZQ"):
            self.pending = ""
            want_lwd = (cand == "ZQ")
            if self.config.match_vim_exit_behavior:
                want_lwd = (cand == "ZZ")
            self.exit_app(write_lwd=want_lwd)
            return
        if cand == "dd":
            self.pending = ""
            self.do_delete(None)
            return
        if cand == "yy":
            self.pending = ""
            self.do_yank(None)
            return
        if self.mode == "visual" and cand == "gg":
            self.pending = ""
            self.go_top()
            return
        if cand.startswith('"'):
            if len(cand) == 2:
                self.pending = cand
                return
            regch = cand[1]
            if len(cand) == 3:
                third = cand[2]
                if self.mode == "visual" and third in ("y", "d"):
                    if regch.isalpha():
                        reg = ('append', regch.lower()) if regch.isupper() else ('set', regch)
                        self.pending = ""
                        if third == "y":
                            self.do_yank(reg)
                        else:
                            self.do_delete(reg)
                    elif regch.isdigit():
                        self.pending = cand[:2]
                    else:
                        self.pending = ""
                        self.set_message("Input not supported.", warn=True)
                        self.mode = "normal" if self.mode == "visual" else self.mode
                    return
                if third == "p" and self.mode == "normal":
                    if regch.isalnum():
                        self.pending = ""
                        self.do_put(regch)
                    else:
                        self.pending = ""
                        self.set_message("Input not supported.", warn=True)
                    return
                if third in ("y", "d") and self.mode == "normal":
                    if regch.isdigit():
                        self.pending = cand
                        self.pending_weird_digit = True
                        return
                    self.pending = cand
                    return
                # anything else: keep accumulating for now
                self.pending = cand
                return
            if len(cand) == 4 and self.mode == "normal":
                if cand[2] in ("y", "d") and cand[3] == cand[2]:
                    regch = cand[1]
                    self.pending = ""
                    if regch.isalpha():
                        reg = ('append', regch.lower()) if regch.isupper() else ('set', regch)
                        if cand[2] == "y":
                            self.do_yank(reg)
                        else:
                            self.do_delete(reg)
                    else:
                        self.set_message("Input not supported.", warn=True)
                    return
                self.pending = ""
                self.clear_message()
                return
            if len(cand) >= 4:
                self.pending = ""
                self.clear_message()
                return
            self.pending = cand
            return
        # two-char sequences that did not match (g?, d?, y?, Z?)
        if len(cand) == 2 and cand[0] in "gdyZ":
            self.pending = ""
            self.clear_message()
            return
        self.pending = ""

    def handle_normal_char(self, ch):
        if self.pending:
            self.handle_pending(ch)
            return
        if self.mode == "visual":
            self.handle_visual_char(ch)
            return
        if ch in "gdyZ\"":
            self.pending = ch
