    # ------------------------------------------------------------------
    # preview content
    def is_image_data(self, data):
        if len(data) >= 3 and data[:3] == b"\xff\xd8\xff" and len(data) >= 4 and data[3] in (0xE0, 0xE1, 0xE2, 0xE3, 0xE8, 0xEE, 0xDB):
            return True
        if data[:8] == b"\x89PNG\r\n\x1a\n":
            return True
        if data[:6] in (b"GIF87a", b"GIF89a"):
            return True
        if len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP":
            return True
        if len(data) >= 2 and data[:2] == b"BM":
            return True
        if data[:4] in (b"II*\x00", b"MM\x00*"):
            return True
        if data[:4] == b"\x00\x00\x01\x00":
            return True
        if len(data) >= 12 and data[4:8] == b"ftyp" and data[8:12] in (b"avif", b"avis"):
            return True
        return False

    def get_preview(self, pw, chafa_h):
        """Returns (lines, is_register)."""
        if self.show_registers:
            if not self.registers:
                return (["No registers found."], True)
            lines = []
            for key in sorted(self.registers.keys()):
                names = " ".join(disp for (_s, disp) in self.registers[key])
                logical = f'"{key} {names}'
                lines.extend(split_width(logical, pw))
            return (lines, True)
        item = self.selected()
        if item is None:
            return ([], False)
        if item.is_dir:
            try:
                names = os.listdir(item.path)
            except Exception:
                return ([], False)
            from functools import cmp_to_key

            def child_cmp(a, b):
                ap = os.path.join(item.path, a)
                bp = os.path.join(item.path, b)
                ad = os.path.isdir(ap)
                bd = os.path.isdir(bp)
                if ad != bd:
                    return -1 if ad else 1
                return natural_cmp(a, b, False)

            names.sort(key=cmp_to_key(child_cmp))
            lines = []
            for i, n in enumerate(names):
                prefix = "└" if i == len(names) - 1 else "├"
                lines.append(f"{prefix} {n}")
            return (lines, False)
        # files
        cache_key = (item.path, pw, chafa_h, item.mtime, item.size)
        if cache_key in self._preview_cache:
            return (self._preview_cache[cache_key], False)
        lines = self._read_preview(item, pw, chafa_h)
        self._preview_cache[cache_key] = lines
        return (lines, False)

    def _read_preview(self, item, pw, chafa_h):
        try:
            with open(item.path, "rb") as f:
                data = f.read()
        except Exception:
            return ["(file not readable)"]
        if self.is_image_data(data):
            if self.chafa_available:
                try:
                    out = subprocess.run(
                        ["chafa", "--animate=false", f"--size={pw}x{chafa_h}", item.path],
                        stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=10)
                    text = out.stdout.decode("utf-8", "replace")
                    return text.split("\n")[:-1] if text.endswith("\n") else text.split("\n")
                except Exception:
                    return []
            msg = "From v1.1.0, the image preview needs chafa (>= v1.10.0). For more details, please see help by `:h`"
            return split_width(msg, pw)
        if b"\x00" in data:
            return ["(binary file)"]
        try:
            text = data.decode("utf-8")
        except Exception:
            return []
        if text == "":
            return []
        parts = text.split("\n")
        if text.endswith("\n"):
            parts = parts[:-1]
        lines = []
        for part in parts:
            if part.endswith("\r"):
                part = part[:-1]
            lines.extend(split_width(part, pw))
        return lines

    # ------------------------------------------------------------------
    # rendering
    def geometry(self):
        w, h = self.term_size()
        show = self.show_pane()
        if show and self.split == "Vertical":
            left = w // 2
            return {"w": w, "h": h, "left": left, "preview_x": left + 1,
                    "preview_w": max(0, w - (left + 1)), "status_y": h - 1,
                    "preview_y": 2, "preview_h": max(0, h - 3),
                    "chafa_h": max(0, h - 3), "vertical": True}
        if show and self.split == "Horizontal":
            status_y = h // 2 - 1
            ph = max(0, (h + 1) // 2 - 2)
            return {"w": w, "h": h, "left": w, "preview_x": 0,
                    "preview_w": w, "status_y": status_y,
                    "preview_y": status_y + 2, "preview_h": ph,
                    "chafa_h": ph, "vertical": False}
        return {"w": w, "h": h, "left": w, "preview_x": 0, "preview_w": 0,
                "status_y": h - 1, "preview_y": 2, "preview_h": 0,
                "chafa_h": 0, "vertical": False}

    def status_text(self):
        if self.search_keyword is not None:
            count = len(self.search_matches())
            suffix = "matches" if count > 1 else "match"
            return f" /{self.search_keyword} - {count} {suffix}"
        item = self.selected()
        if item is None:
            return ""
        if item.is_symlink:
            try:
                raw = os.readlink(item.path)
            except Exception:
                raw = ""
            cand = raw if os.path.isabs(raw) else os.path.join(os.getcwd(), raw)
            if os.path.exists(cand):
                resolved = os.path.realpath(cand)
                return f" linked to: {resolved}"
            return " linked to: (invalid path)"
        parts = f" {self.cursor + 1}/{len(self.items)}"
        if not item.is_dir and item.ext is not None:
            parts += f" {item.ext}"
        parts += f" {format_size(item.size)} {item.perm:03o}"
        return parts

    def render(self):
        w, h = self.term_size()
        scr = Screen(w, h)
        if self.help_mode:
            self._render_help(scr)
            return scr
        g = self.geometry()
        left = g["left"]
        # header
        self._draw_header(scr, g)
        # message / prompt row
        self._draw_row1(scr, g)
        # items
        self._draw_items(scr, g)
        # preview
        if self.show_pane():
            self._draw_preview(scr, g)
        # status
        self._draw_status(scr, g)
        # frame cursor
        if self.prompt is not None:
            kind = self.prompt["kind"]
            if kind in ("create_file", "create_dir", "rename"):
                label = {"create_file": "New file: ", "create_dir": "New directory: ", "rename": "New name: "}[kind]
                x = 1 + text_width(label) + text_width(self.prompt["buf"][:self.prompt["cur"]])
            else:
                x = 1 + text_width(self.prompt["buf"][:self.prompt["cur"]])
            self._frame_cursor = (x, 1, True)
        else:
            row = 2 + (self.cursor - self.offset)
            if row < 2:
                row = 2
            if row > g["status_y"] - 1 and not self.show_pane() or (self.show_pane() and self.split == "Horizontal" and row > g["status_y"] - 1):
                row = g["status_y"] - 1
            self._frame_cursor = (0, row, False)
        return scr

    def _draw_header(self, scr, g):
        w = g["w"]
        left = g["left"]
        limit = left if g["vertical"] else w
        segments = [(f" {self.cwd}", ("pal", 6), False)]
        if not os.access(self.cwd, os.W_OK):
            segments.append((" [RO]", ("pal", 1), False))
        if self.git_branch:
            segments.append((" on ", None, False))
            segments.append((self.git_branch, ("pal", 13), True))
        x = 0
        for text, color, bold in segments:
            if x >= limit:
                break
            piece = clip_width(text, limit - x)
            style = (color, None, bold, False)
            scr.text(x, 0, piece, style)
            x += text_width(piece)
        if g["vertical"] and not self.show_registers:
            item = self.selected()
            if item is not None:
                title = clip_width(f"[{item.name}]", g["preview_w"])
                scr.text(g["preview_x"], 0, title, STYLE_DEFAULT)

    def _draw_row1(self, scr, g):
        w = g["w"]
        if self.prompt is not None:
            kind = self.prompt["kind"]
            if kind in ("create_file", "create_dir", "rename"):
                label = {"create_file": "New file: ", "create_dir": "New directory: ", "rename": "New name: "}[kind]
                text = " " + label + self.prompt["buf"]
            else:
                text = " " + self.prompt["buf"]
            scr.text(0, 1, clip_width(text, w), STYLE_DEFAULT)
            return
        if self.pending:
            scr.text(0, 1, clip_width(" " + self.pending, w), STYLE_DEFAULT)
            return
        if self.message is not None:
            text, warn = self.message
            if warn:
                scr.text(0, 1, " ", STYLE_DEFAULT)
                scr.text(1, 1, clip_width(text, max(0, w - 1)), (("pal", 7), ("pal", 9), False, False))
            else:
                scr.text(0, 1, clip_width(" " + text, w), STYLE_DEFAULT)

    def _marker_visible(self):
        if self.prompt is not None:
            kind = self.prompt["kind"]
            if kind == "rename":
                return True
            if kind == "search":
                return getattr(self, "_search_edited", False)
            return False
        return True

    def _draw_items(self, scr, g):
        left = g["left"]
        lh = self.list_height()
        show_date = left >= 28
        date_w = 17 if show_date else 0
        name_cap = max(0, left - 2 - date_w)
        marker = self._marker_visible()
        if not self.items:
            if marker:
                scr.text(0, 2, ">", STYLE_DEFAULT)
            return
        for idx in range(self.offset, min(len(self.items), self.offset + lh)):
            row = 2 + (idx - self.offset)
            if row >= g["status_y"]:
                break
            item = self.items[idx]
            is_cursor = idx == self.cursor
            scr.text(0, row, ">" if (is_cursor and marker) else " ", STYLE_DEFAULT)
            # colour
            if item.dirty:
                color = self.config.dirty_fg
            elif item.is_symlink:
                color = self.config.symlink_fg
            elif item.is_dir:
                color = self.config.dir_fg
            else:
                color = self.config.file_fg
            in_visual = self.mode == "visual" and min(self.visual_anchor, self.cursor) <= idx <= max(self.visual_anchor, self.cursor)
            style = (color, None, False, in_visual)
            if text_width(item.name) > name_cap:
                name_disp = truncate_width(item.name, name_cap)
            else:
                name_disp = item.name
            scr.text(2, row, name_disp, style)
            if show_date:
                datestr = time.strftime("%Y-%m-%d %H:%M", time.localtime(item.mtime))
                scr.text(left - 17, row, " " + datestr, style)

    def _draw_preview(self, scr, g):
        pw = g["preview_w"]
        if pw <= 0:
            return
        lines, is_register = self.get_preview(pw, g["chafa_h"])
        style = STYLE_DEFAULT if is_register else (("pal", 8), None, False, False)
        visible = lines[self.preview_scroll:self.preview_scroll + g["preview_h"]]
        for i, line in enumerate(visible):
            y = g["preview_y"] + i
            if y >= g["h"]:
                break
            scr.text(g["preview_x"], y, clip_width(line, pw), style)

    def _draw_status(self, scr, g):
        text = self.status_text()
        if not text:
            return
        y = g["status_y"]
        if g["vertical"]:
            style = (None, None, False, True)
            for x in range(g["left"]):
                scr.put(x, y, " ", style)
            scr.text(0, y, clip_width(text, g["left"]), style)
        else:
            style = (None, None, False, True)
            scr.text(0, y, clip_width(text, g["w"]), style)

    def _render_help(self, scr):
        w, h = scr.w, scr.h
        content_rows = max(0, h - 1)
        lines = self.help_lines[self.help_scroll:self.help_scroll + content_rows]
        for i, line in enumerate(lines):
            scr.text(0, i, clip_width(line, w), STYLE_DEFAULT)
        more = self.help_scroll + content_rows < len(self.help_lines)
        if more:
            scr.text(0, h - 1, "...", (None, None, False, True))
            self._frame_cursor = (3, h - 1, False)
        else:
            # position at the end of the final help line when visible
            last_idx = len(self.help_lines) - 1
            if self.help_scroll <= last_idx < self.help_scroll + content_rows:
                self._frame_cursor = (text_width(self.help_lines[last_idx]), last_idx - self.help_scroll, False)
            else:
                self._frame_cursor = (0, 0, False)

