    # ------------------------------------------------------------------
    # main loop
    def run(self, term):
        self.term = term
        # presence probes (spawn success counts as available)
        for name, attr in (("zoxide", "zoxide_available"), ("chafa", "chafa_available")):
            try:
                subprocess.run([name, "--help"], stdout=subprocess.DEVNULL,
                               stderr=subprocess.DEVNULL, timeout=5)
                setattr(self, attr, True)
            except Exception:
                setattr(self, attr, False)
        term.enter()
        try:
            while not self.exited:
                scr = self.render()
                data = render_screen(scr)
                curx, cury, curvis = self._frame_cursor
                if curvis:
                    data += f"\x1b[{cury + 1};{curx + 1}H\x1b[?25h"
                else:
                    data += f"\x1b[{cury + 1};{curx + 1}H\x1b[?25l"
                try:
                    os.write(1, data.encode("utf-8", "surrogateescape"))
                except OSError:
                    break
                ev = term.poll_event(0.05)
                if ev is None:
                    continue
                if ev.kind == "eof":
                    break
                try:
                    self.handle_event(ev)
                except FatalError:
                    raise
        finally:
            if not getattr(self, "_fatal_no_restore", False):
                term.leave()


